"""Every relative link in the lesson's Markdown files must resolve."""

from __future__ import annotations

import re
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parent.parent
SKIP_PARTS = {".git", ".venv", "venv", "node_modules", ".pytest_cache"}
# Spec Kit's own files: generated by the tool, not part of the lesson text.
VENDORED = ROOT / "demo" / "experiment-runs-reference" / ".claude"
VENDORED_SPECIFY = ROOT / "demo" / "experiment-runs-reference" / ".specify"

LINK = re.compile(r"(?<!!)\[[^\]]*\]\(([^)\s]+)\)")
FENCE = re.compile(r"^(```|~~~)")


def markdown_files() -> list[Path]:
    files = []
    for path in sorted(ROOT.rglob("*.md")):
        if SKIP_PARTS.intersection(path.relative_to(ROOT).parts):
            continue
        if VENDORED in path.parents or VENDORED_SPECIFY in path.parents:
            continue
        files.append(path)
    return files


def links(path: Path) -> list[str]:
    found: list[str] = []
    in_fence = False
    for line in path.read_text(encoding="utf-8").splitlines():
        if FENCE.match(line.strip()):
            in_fence = not in_fence
            continue
        if not in_fence:
            found.extend(LINK.findall(line))
    return found


def slug(heading: str) -> str:
    """GitHub's heading anchor: lowercase, punctuation dropped, spaces to dashes."""
    text = re.sub(r"[`*_]", "", heading.strip().lower())
    text = re.sub(r"[^\w\- ]", "", text)
    return text.replace(" ", "-")


def anchors(path: Path) -> set[str]:
    seen: dict[str, int] = {}
    result: set[str] = set()
    in_fence = False
    for line in path.read_text(encoding="utf-8").splitlines():
        if FENCE.match(line.strip()):
            in_fence = not in_fence
            continue
        match = re.match(r"^#{1,6}\s+(.*)$", line)
        if in_fence or not match:
            continue
        base = slug(match.group(1))
        count = seen.get(base, 0)
        seen[base] = count + 1
        result.add(base if count == 0 else f"{base}-{count}")
    return result


def test_markdown_files_are_found() -> None:
    names = {p.relative_to(ROOT).as_posix() for p in markdown_files()}
    assert {"README.md", "lab/README.md", "demo/README.md"} <= names


@pytest.mark.parametrize(
    "path", markdown_files(), ids=lambda p: p.relative_to(ROOT).as_posix()
)
def test_relative_links_resolve(path: Path) -> None:
    broken = []
    for target in links(path):
        if re.match(r"^[a-z]+:", target):
            continue  # http:, https:, mailto:
        file_part, _, anchor = target.partition("#")
        destination = (path.parent / file_part).resolve() if file_part else path
        if not destination.exists():
            broken.append(f"{target} (missing file)")
        elif (
            anchor
            and destination.suffix == ".md"
            and anchor not in anchors(destination)
        ):
            broken.append(f"{target} (missing anchor)")
    assert not broken, f"{path.relative_to(ROOT)}: {broken}"


def test_lesson_document_exists() -> None:
    assert (ROOT / "docs" / "spec-driven-development.docx").is_file()
